import{_ as a,H as o,f as c,i as d}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"Plan（計画）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/plan.md","filePath":"ja/skills/plan.md"}'),t={name:"ja/skills/plan.md"};function s(n,e,p,l,i,r){return o(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="plan-計画" tabindex="-1">Plan（計画） <a class="header-anchor" href="#plan-計画" aria-label="Permalink to &quot;Plan（計画）&quot;">​</a></h1><p><code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>。仕様を参照し、繰り返さない。</p><p>未解決の仕様ノートが実装またはタスク順序に影響する場合、<code>design</code> に戻る。</p><h2 id="マイルストーンタスク-各30〜60分" tabindex="-1">マイルストーンタスク（各30〜60分） <a class="header-anchor" href="#マイルストーンタスク-各30〜60分" aria-label="Permalink to &quot;マイルストーンタスク（各30〜60分）&quot;">​</a></h2><p>各タスクは <code>- [ ] T&lt;n&gt;: &lt;名前&gt;</code> — 常にチェックボックス、見出しではない。<code>tdd</code>/<code>subagents</code> が完了時に <code>- [x]</code> に変更。<code>ship</code> はすべての <code>- [ ]</code> が完了するまで実行を拒否する。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;一行&gt;</span></span>
<span class="line"><span>files:      &lt;パス&gt;</span></span>
<span class="line"><span>acceptance: &lt;テストまたはコマンド&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>コードなし。ステップなし。Acceptanceは実行可能：テスト名、コマンド、またはスクリプトチェック。各タスクはリポジトリをグリーンな状態に保つ。</p><p>独立したタスクをマーク：<code>[parallel] T3, T4, T5</code>。</p><p>共有契約、状態、エラー、acceptanceが閉じている場合のみ <code>[parallel]</code> をマーク。</p><p><strong>原子的展開は派遣時に遅延</strong> — <code>subagents</code> が派遣時にマイルストーンを2〜5分のステップに展開する。ここではしない。</p><p><strong>新プロジェクト</strong>：初期化タスクを派生させる — スキャフォールドコード、テスト、CI。常に含む：<code>README.md</code>、<code>CHANGELOG.md</code>、<code>.gitignore</code>、<code>Makefile</code>（または同等のタスクランナー設定）。</p><h2 id="計画に含めないもの" tabindex="-1">計画に含めないもの <a class="header-anchor" href="#計画に含めないもの" aria-label="Permalink to &quot;計画に含めないもの&quot;">​</a></h2><p>背景、アーキテクチャ、理由（仕様）、CIコマンド、コピーペーストのacceptance。</p><h2 id="ローリングウェーブ" tabindex="-1">ローリングウェーブ <a class="header-anchor" href="#ローリングウェーブ" aria-label="Permalink to &quot;ローリングウェーブ&quot;">​</a></h2><p>仕様に <code>## Roadmap</code> がある？ <code>← 今詳細に計画</code> とマークされたマイルストーンだけを展開する。他はスタブのままにする。</p><p><code>ship</code> 後：<code>← 今詳細に計画</code> マーカーを次のマイルストーンに移動し（その <code>← stub</code> を <code>← 今詳細に計画</code> に変更）、学んだことに基づいて更新し、展開する。マイルストーンのゴールが本質的に変わった場合のみ <code>design</code> に戻る。</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><code>tdd</code>/<code>subagents</code> に引き渡す前に <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code> がディスク上に存在すること。</p><p>ユーザーと計画を確認する。</p><p><code>[parallel]</code> が多い → <code>subagents</code>。そうでなければ → <code>tdd</code>。</p>`,20)])])}const u=a(t,[["render",s]]);export{g as __pageData,u as default};
